import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';

/**
 * Get invoices that are overdue as of a given date.
 * @param {Array} invoices - all invoices in the system
 * @param {string} asOf - cutoff date in YYYY-MM-DD format
 * @returns {Array} - array of { number, customerId, dueDate, daysOverdue, due }, sorted by daysOverdue descending
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter(inv =>
      (inv.status === 'issued' || inv.status === 'partially_paid') &&
      inv.dueDate < asOf
    )
    .map(inv => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Get a summary of VAT by rate across invoices.
 * @param {Array} invoices - all invoices in the system
 * @returns {Array} - array of { rate, base, vat }, sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = {};

  invoices
    .filter(inv => ['issued', 'partially_paid', 'paid'].includes(inv.status))
    .forEach(inv => {
      inv.lines.forEach(line => {
        const rate = line.vatRate;
        const base = lineTotal(line) - lineDiscount(line);
        const vat = lineVat(line);

        if (!vatMap[rate]) {
          vatMap[rate] = { rate, base: 0, vat: 0 };
        }
        vatMap[rate].base += base;
        vatMap[rate].vat += vat;
      });
    });

  return Object.values(vatMap).sort((a, b) => b.rate - a.rate);
}

